import importlib

def test_no_hardcoded_credentials():
    db = importlib.import_module("app.db")
    for secret_name in ("DB_PASSWORD", "API_TOKEN"):
        assert not hasattr(db, secret_name), f"{secret_name} should not be defined in app.db"

def test_search_tasks_return_type(monkeypatch):
    # Mock sqlite3 to return a known row structure
    class MockCursor:
        def fetchall(self):
            return [(1, "Sample", "desc", 0)]
    class MockConn:
        def execute(self, query, params=None):
            return MockCursor()
        def __enter__(self):
            return self
        def __exit__(self, exc_type, exc, tb):
            pass
    def mock_connect(db):
        return MockConn()
    monkeypatch.setattr('sqlite3.connect', mock_connect)
    from app.db import search_tasks
    result = search_tasks('Sample')
    assert isinstance(result, list)
    assert all(isinstance(row, dict) for row in result), "Rows should be dicts"

def test_percent_zero_denominator():
    from app.utils import percent
    assert percent(5, 0) == 0.0

def test_complete_task_missing_returns_false():
    result = complete_task(12345, 1)  # assuming 12345 does not exist
    assert result is False

def test_handle_update_email_invalid_email():
    response = handle_update_email(user_id=1, email="not-an-email")
    assert response == {"status": 400, "error": "invalid user or email"}

def test_handle_update_email_missing_user():
    response = handle_update_email(user_id=999, email="test@example.com")
    assert response == {"status": 400, "error": "invalid user or email"}
